<script setup lang="ts">
import { computed, defineAsyncComponent, shallowRef } from 'vue'
import { useSkyStore } from '../../stores/sky'
import { opsRead, type OpsPage, type OpsRow } from '../../api/operations'
import { getRoute, suggestRoute, saveRoute } from '../../api/routes'
import type { RouteDetail, RouteEvaluation, RouteSketch } from '@sky/routes'
import type { RunInput } from '../../types/workbench'
import type { GeoBounds } from '../../utils/spatialSelection.mjs'
import SpatialSelectionMap from './SpatialSelectionMap.vue'
const CityViewport = defineAsyncComponent(() => import('../business/CityViewport.vue'))
const emit = defineEmits<{ analyze: [input: RunInput] }>()
const sky=useSkyStore(), bounds=shallowRef<GeoBounds>(), rows=shallowRef<OpsRow[]>([]), total=shallowRef(0), selected=shallowRef<string[]>([]), busy=shallowRef(false), error=shallowRef(''), consent=shallowRef(false)
const taskId=shallowRef(''), original=shallowRef<RouteDetail>(), candidate=shallowRef<RouteEvaluation>(), display=shallowRef<'original'|'candidate'>('original'), reason=shallowRef(''), map=shallowRef(false)
const sketch=computed<RouteSketch|undefined>(()=>{ const p=display.value==='candidate'?candidate.value?.plan:original.value?.plan; return p?{points:p.points,waypoints:p.waypoints,altitude:p.cruiseAltitude,selected:-1}:undefined })
async function query(box:GeoBounds) { bounds.value=box; rows.value=[];selected.value=[];total.value=0;busy.value=true;error.value=''; try { const value=await opsRead<OpsPage>('/spatial/tasks?'+new URLSearchParams(Object.entries(box).map(([k,v])=>[k,String(v)]))); rows.value=value.rows;total.value=value.total } catch(e){ error.value=String(e) } finally {busy.value=false} }
function toggle(id:string,checked:boolean){ selected.value=checked?[...selected.value,id]:selected.value.filter(v=>v!==id) }
function analyze(){ if(!selected.value.length||!consent.value)return; emit('analyze',{mode:'live',external_allowed:true,source_kind:'none',source_id:'',compare_id:'',parent_id:'',question:`请查询并分析以下明确选中的待分配任务：${selected.value.join('、')}。说明资源约束、需要补充的信息及调度建议。不要自动生成方案、分配或执行。`}) }
async function compare(){ busy.value=true;error.value='';original.value=undefined;candidate.value=undefined; try { const detail=await getRoute(taskId.value);original.value=detail;const value=await suggestRoute(taskId.value,{expectedRevision:detail.plan.revision,waypoints:detail.plan.waypoints,reason:'用户请求比较绕行候选，尚未保存'});candidate.value=value;display.value='candidate' }catch(e){error.value=String(e)}finally{busy.value=false} }
async function save(){ if(!original.value||!candidate.value||!reason.value.trim())return;busy.value=true;error.value='';try{ const result=await saveRoute(taskId.value,{expectedRevision:original.value.plan.revision,waypoints:candidate.value.plan.waypoints,reason:reason.value});original.value={...original.value,plan:result.plan};candidate.value=undefined;display.value='original';reason.value='' }catch(e){error.value=String(e)}finally{busy.value=false} }
</script>
<template><section class="spatial"><h2>地图框选与方案比较</h2><p v-if="error" role="alert">{{ error }}</p><SpatialSelectionMap :stations="sky.snapshot.stations" :disabled="busy" @select="query"/><p v-if="bounds">框选：{{ bounds }} · 全库起终点匹配 {{ total }} 项，最多显示前100项待分配任务；超过20项请缩小区域或手动选择。</p><label v-for="r in rows" :key="String(r.id)" class="task"><input type="checkbox" :checked="selected.includes(String(r.id))" :disabled="busy" @change="toggle(String(r.id),($event.target as HTMLInputElement).checked)">{{ r.title }} · {{ r.id }} · {{ r.startStationName }} → {{ r.endStationName }}</label><label><input v-model="consent" type="checkbox">允许将所选任务和后续检索证据发送给外部模型做只读分析</label><button :disabled="busy||!sky.canOperate||!consent||!selected.length||selected.length>20" @click="analyze">分析所选 {{ selected.length }} 项任务</button><p>查询不改变任务状态；AI建议完成后，仍需在运行中心明确选择任务并生成Java方案。</p><h3>已保存航线与绕行候选</h3><label>任务编号<input v-model="taskId" maxlength="40"></label><button :disabled="busy||!taskId||!sky.canOperate" @click="compare">重新读取并计算候选（不保存）</button><div v-if="original"><p>原航线：{{ original.plan.distanceMeters.toFixed(0) }}m · {{ original.plan.durationSeconds }}仿真秒 · v{{ original.plan.revision }}</p><p v-if="candidate">候选：{{ candidate.plan.distanceMeters.toFixed(0) }}m · {{ candidate.plan.durationSeconds }}仿真秒 · 距离变化 {{ (candidate.plan.distanceMeters-original.plan.distanceMeters).toFixed(0) }}m · {{ candidate.allowed?'当前校验允许':'当前校验不通过' }}</p><p v-if="candidate">约束：{{ candidate.constraints.join('；')||'无额外约束提示' }}</p><select v-model="display"><option value="original">显示原航线</option><option value="candidate" :disabled="!candidate">显示候选</option></select><button @click="map=!map">{{ map?'收起':'查看' }}三维航线</button><div v-if="map" class="map"><CityViewport :aircraft="sky.snapshot.aircraft" :stations="sky.snapshot.stations" :tasks="sky.snapshot.tasks" :zones="sky.snapshot.airspaceZones" :route-sketch="sketch" /></div><label v-if="candidate">保存原因<input v-model="reason" maxlength="500"></label><button v-if="candidate" :disabled="busy||!sky.canOperate||!candidate.allowed||!reason.trim()" @click="save">审查后保存候选版本</button></div><p>绕行只考虑已配置矩形空域，无建筑/地形感知。保存与起飞仍由Java重查约束；资源变化可能使旧建议失效。</p></section></template>
<style scoped>.spatial{padding:20px;background:#102537;border:1px solid #31546b}.spatial p{color:#9ebfd2;line-height:1.8;font-size:13px}.task{display:block;padding:8px;border-bottom:1px solid #31546b}.spatial input:not([type=checkbox]),.spatial select{padding:8px;background:#081c2a;color:#e0eff7;border:1px solid #36536b;margin:8px}.map{height:500px;margin:12px 0}</style>
